-- 0021_add_intake_dispute — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- SOP-DEL-01 §9 Disputes (E2 AC5): "If Sales disagrees with a Returned decision, the Sales Lead escalates to [the
-- sponsor], who decides within 2 working days. Work does not start while the dispute is open." One dispute per
-- Returned decision. Internal only, like the decision itself (0009): no client or partner policy.
CREATE TABLE intake_dispute (
  id           uuid PRIMARY KEY,
  client_id    uuid NOT NULL,
  decision_id  uuid NOT NULL UNIQUE,
  reason       text NOT NULL CHECK (btrim(reason) <> ''),
  raised_by    uuid NOT NULL,
  raised_at    timestamptz NOT NULL DEFAULT now(),
  -- The sponsor's 2-working-day deadline (§9), computed by the command.
  due_on       date NOT NULL,
  -- upheld: the return stands; overturned: the card goes back to the Delivery Director for a new review.
  outcome      text CHECK (outcome IN ('upheld', 'overturned')),
  outcome_note text,
  decided_by   uuid,
  decided_at   timestamptz,
  created_at   timestamptz NOT NULL DEFAULT now(),
  archived_at  timestamptz,
  CHECK ((outcome IS NULL) = (decided_at IS NULL) AND (outcome IS NULL) = (decided_by IS NULL)),
  FOREIGN KEY (decision_id, client_id) REFERENCES intake_decision (id, client_id)
);
CREATE INDEX intake_dispute_client ON intake_dispute (client_id);
-- Overdue checks scan open disputes by deadline.
CREATE INDEX intake_dispute_open ON intake_dispute (due_on) WHERE outcome IS NULL;

ALTER TABLE intake_dispute ENABLE ROW LEVEL SECURITY;
CREATE POLICY intake_dispute_internal ON intake_dispute FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
-- No DELETE: archive with archived_at (SOP-DEL-02 "never delete").
GRANT SELECT, INSERT, UPDATE ON intake_dispute TO ocs_app;
